def compute(vars):
    beginning = vars["v1"]
    ending = vars["v2"]
    net_change = ending - beginning
    return {
        "value": net_change,
        "trace": {
            "beginning_balance": beginning,
            "ending_balance": ending,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
